components.css:
.ds-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:10px 16px;border:1px solid transparent;border-radius:3px;font-family:var(--font-inter,Inter,system-ui,sans-serif);font-size:14px;font-weight:500;line-height:1.45;cursor:pointer;transition:background-color 150ms ease,border-color 150ms ease,color 150ms ease,opacity 150ms ease}
.ds-btn-primary{background:var(--ink, #111112);color:var(--ink-on, #fbfbfa);border-color:var(--ink, #111112)}
.ds-btn-primary:hover{opacity:.86}
.ds-btn-primary:active{transform:translateY(1px)}
.ds-btn-primary:focus-visible{outline:2px solid var(--focus, #2f5fd0);outline-offset:2px}
.ds-btn-primary:disabled{opacity:.5;cursor:not-allowed}

.ds-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:10px 16px;border:1px solid transparent;border-radius:3px;font-family:var(--font-inter,Inter,system-ui,sans-serif);font-size:14px;font-weight:500;line-height:1.45;cursor:pointer;transition:background-color 150ms ease,border-color 150ms ease,color 150ms ease}
.ds-btn-secondary{background:var(--paper, #fbfbfa);color:var(--ink, #111112);border-color:var(--n-3, #c9c9c5)}
.ds-btn-secondary:hover{background:var(--sunken, #eeeeec);border-color:var(--n-2, #8a8a86)}
.ds-btn-secondary:active{transform:translateY(1px)}
.ds-btn-secondary:focus-visible{outline:2px solid var(--focus, #2f5fd0);outline-offset:2px}

.ds-field{font-family:var(--font-inter,Inter,system-ui,sans-serif)}
.ds-label{display:block;margin-bottom:6px;font-size:11px;font-weight:600;letter-spacing:.09em;text-transform:uppercase;line-height:1;color:var(--n-1, #6b6b68)}
.ds-input{display:block;width:100%;min-height:44px;padding:10px 12px;background:var(--paper, #fbfbfa);color:var(--ink, #111112);border:1px solid var(--n-3, #c9c9c5);border-radius:3px;font-family:inherit;font-size:16px;transition:border-color 150ms ease,background-color 150ms ease}
.ds-input::placeholder{color:var(--n-2, #8a8a86)}
.ds-input:hover{border-color:var(--n-2, #8a8a86)}
.ds-input:focus{border-color:var(--ink, #111112);outline:2px solid var(--focus, #2f5fd0);outline-offset:1px}
.ds-input[aria-invalid="true"]{border-color:var(--wrong, #b03030)}
.ds-hint{margin:6px 0 0;font-size:12px;color:var(--n-1, #6b6b68)}

.ds-chips{display:flex;align-items:center;gap:4px;font-family:var(--font-inter,Inter,system-ui,sans-serif)}
.ds-chips-label{margin-right:4px;font-size:11px;font-weight:600;letter-spacing:.09em;text-transform:uppercase;line-height:1;color:var(--n-1, #6b6b68)}
.ds-chip{padding:4px 8px;border:1px solid var(--rule, #e2e2de);border-radius:3px;background:transparent;color:var(--n-1, #6b6b68);font-family:inherit;font-size:12px;cursor:pointer;transition:background-color 150ms ease,color 150ms ease,border-color 150ms ease}
.ds-chip:hover{background:var(--sunken, #eeeeec);color:var(--ink, #111112)}
.ds-chip:focus-visible{outline:2px solid var(--focus, #2f5fd0);outline-offset:2px}
.ds-chip[aria-pressed="true"]{background:var(--ink, #111112);border-color:var(--ink, #111112);color:var(--ink-on, #fbfbfa);font-weight:500}

.ds-pick{font-family:var(--font-inter,Inter,system-ui,sans-serif);border-bottom:1px solid var(--rule, #e2e2de);padding-bottom:10px}
.ds-pick-meta{display:flex;align-items:baseline;gap:8px;padding:8px 0}
.ds-pick-time{font-family:var(--font-mono-face,"JetBrains Mono",ui-monospace,monospace);font-size:12px;font-variant-numeric:tabular-nums;color:var(--n-1, #6b6b68)}
.ds-pick-live{display:inline-flex;align-items:center;gap:4px;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.08em;color:var(--live, #a8650b)}
.ds-live-dot{width:6px;height:6px;border-radius:999px;background:currentColor;animation:ds-live-pulse 2s ease-in-out infinite}
@keyframes ds-live-pulse{0%,100%{opacity:1}50%{opacity:.35}}
.ds-pick-sides{display:grid;grid-template-columns:1fr auto 1fr;align-items:stretch;gap:6px}
.ds-side{position:relative;display:flex;align-items:center;gap:10px;min-height:44px;width:100%;padding:8px 10px;text-align:left;border:1px solid var(--rule, #e2e2de);border-radius:3px;background:var(--paper, #fbfbfa);color:var(--ink, #111112);font-family:inherit;cursor:pointer;transition:background-color 150ms ease,border-color 150ms ease}
.ds-side:hover{border-color:var(--n-3, #c9c9c5);background:var(--panel, #f4f4f2)}
.ds-side:focus-visible{outline:2px solid var(--focus, #2f5fd0);outline-offset:2px}
.ds-side-sel{background:var(--ink, #111112);border-color:var(--ink, #111112);color:var(--ink-on, #fbfbfa)}
.ds-side-sel:hover{background:var(--ink, #111112);border-color:var(--ink, #111112)}
.ds-side:last-of-type{flex-direction:row-reverse;text-align:right}
.ds-side-lost{opacity:.55}
.ds-logo{width:26px;height:26px;flex-shrink:0}
.ds-side-text{display:flex;flex-direction:column;min-width:0;flex:1}
.ds-side:last-of-type .ds-side-text{align-items:flex-end}
.ds-side-abbr{font-size:16px;font-weight:600;line-height:1;letter-spacing:-.02em}
.ds-side-name{font-size:12px;line-height:1.2;color:var(--n-1, #6b6b68)}
.ds-side-sel .ds-side-name{color:var(--ink-on, #fbfbfa);opacity:.7}
.ds-score{font-family:var(--font-mono-face,"JetBrains Mono",ui-monospace,monospace);font-size:20px;line-height:1;font-weight:700;font-variant-numeric:tabular-nums}
.ds-side-lost .ds-score{font-weight:500;color:var(--n-2, #8a8a86)}
.ds-badge{position:absolute;top:-1px;right:-1px;display:flex;align-items:center;justify-content:center;width:16px;height:16px;border-radius:0 0 0 3px;background:var(--correct, #1f7a4d);color:var(--paper, #fbfbfa)}
.ds-at{align-self:center;padding:0 2px;font-size:12px;font-weight:500;color:var(--n-3, #c9c9c5)}

.ds-rail{border-bottom:1px solid var(--rule, #e2e2de);font-family:var(--font-inter,Inter,system-ui,sans-serif)}
.ds-rail-track{display:flex;gap:1px;overflow-x:auto;padding-bottom:8px;-webkit-mask-image:linear-gradient(to right,#000 0,#000 calc(100% - 28px),transparent 100%);mask-image:linear-gradient(to right,#000 0,#000 calc(100% - 28px),transparent 100%);scrollbar-width:none}
.ds-rail-track::-webkit-scrollbar{display:none}
.ds-rail-cell{display:flex;flex-direction:column;align-items:center;justify-content:center;height:44px;min-width:44px;flex-shrink:0;padding:0 8px;font-size:12px;font-weight:500;font-variant-numeric:tabular-nums;text-decoration:none;color:var(--n-1, #6b6b68);transition:background-color 150ms ease,color 150ms ease}
.ds-rail-cell:hover{background:var(--sunken, #eeeeec);color:var(--ink, #111112)}
.ds-rail-cell:focus-visible{outline:2px solid var(--focus, #2f5fd0);outline-offset:-2px}
.ds-rail-cell-active{background:var(--ink, #111112);color:var(--ink-on, #fbfbfa);font-weight:600}
.ds-rail-cell-off{color:var(--n-3, #c9c9c5);cursor:default}
.ds-rail-done{display:block;margin-top:4px;width:12px;height:1px;background:var(--n-3, #c9c9c5)}
.ds-rail-cell-active .ds-rail-done{background:var(--ink-on, #fbfbfa);opacity:.5}

.ds-tabs{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--rule, #e2e2de);background:var(--paper, #fbfbfa);font-family:var(--font-inter,Inter,system-ui,sans-serif)}
.ds-tab{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;height:56px;text-decoration:none;color:var(--n-2, #8a8a86);transition:color 150ms ease}
.ds-tab span{font-size:11px;font-weight:500;letter-spacing:.06em;text-transform:uppercase}
.ds-tab:focus-visible{outline:2px solid var(--focus, #2f5fd0);outline-offset:-2px}
.ds-tab-active{color:var(--ink, #111112)}
.ds-tab-active span{font-weight:600}
